import axios from "axios";
import { handleAuthFailure, getAuthToken } from "./utils/auth.js";

// Create axios instance with default configuration
const axiosInstance = axios.create({
  baseURL: "https://backend.alaqdk.com/api/",
  headers: {
    'Authorization': 'Bearer ' + getAuthToken()
  }
});

// Add default language header

// Add request interceptor to update auth token
axiosInstance.interceptors.request.use(
  (config) => {
    const token = getAuthToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Add response interceptor to handle authentication failures
axiosInstance.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    // Handle authentication errors (401 Unauthorized, 403 Forbidden)
    if (error.response && (error.response.status === 401 || error.response.status === 403)) {
      // Use the auth utility function to handle the failure
      handleAuthFailure(
        window.router, 
        window.store, 
        window.getToast ? window.getToast() : null, 
        "Authentication failed. Please login again."
      );
    }
    
    return Promise.reject(error);
  }
);

export default axiosInstance;
 