<template>
  <div class="star-rating" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="stars-container">
      <span
        v-for="star in 5"
        :key="star"
        class="star"
        :class="{
          'filled': star <= Math.floor(numericRating),
          'half-filled': star === Math.ceil(numericRating) && numericRating % 1 !== 0,
          'empty': star > Math.ceil(numericRating)
        }"
      >
        <svg
          v-if="star <= Math.floor(numericRating)"
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"
            fill="#FBB040"
          />
        </svg>
        <svg
          v-else-if="star === Math.ceil(numericRating) && numericRating % 1 !== 0"
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <defs>
            <linearGradient id="halfStar">
              <stop offset="50%" stop-color="#FBB040" />
              <stop offset="50%" stop-color="#E0E0E0" />
            </linearGradient>
          </defs>
          <path
            d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"
            fill="url(#halfStar)"
          />
        </svg>
        <svg
          v-else
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"
            fill="#E0E0E0"
          />
        </svg>
      </span>
    </div>
    <span v-if="showValue" class="rating-value">{{ numericRating }}</span>
  </div>
</template>

<script>
export default {
  name: 'StarRating',
  props: {
    rating: {
      type: [Number, String],
      required: true,
      default: 0
    },
    showValue: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    numericRating() {
      return parseFloat(this.rating) || 0;
    }
  }
}
</script>

<style scoped>
.star-rating {
  display: flex;
  align-items: center;
  gap: 4px;
}

.stars-container {
  display: flex;
  align-items: center;
  gap: 2px;
}

.star {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: default;
}

.star svg {
  transition: all 0.2s ease;
}

.star.filled svg {
  fill: #FBB040;
}

.star.half-filled svg {
  fill: url(#halfStar);
}

.star.empty svg {
  fill: #E0E0E0;
}

.rating-value {
  font-size: 14px;
  font-weight: 500;
  color: #333;
  margin-left: 4px;
}

/* RTL Support */
[dir="rtl"] .rating-value {
  margin-left: 0;
  margin-right: 4px;
}
</style> 