<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="table-container">
        <div class="headerTable">
          <div class="icon_text">
            <div class="icon">
              <SvgIcon name="icon-container2"></SvgIcon>
            </div>
            <p>{{ $t("Aside_LI11") }}</p>
          </div>
          <div class="search_add">
            <div class="search">
              <input type="text" v-model="filter" :placeholder="$t('search')" />
              <SvgIcon class="svg" name="search"></SvgIcon>
            </div>
            <button class="search-button" @click="openPopup('add')">
              <p class="addRestbtn">{{ $t("add") }}</p>
              <span class="icon">
                <SvgIcon name="add"></SvgIcon>
              </span>
            </button>
          </div>
        </div>
        
        <!-- Loading state -->
        <div v-if="loading" class="loading-container">
          <LoadingHere />
        </div>
        
        <!-- Error state -->
        <div v-else-if="error" class="error-container">
          <p class="error-message">{{ error }}</p>
          <button @click="fetchUserData" class="retry-button">Retry</button>
        </div>
        
        <!-- Table content -->
        <div v-else class="table-responsive">
          <table>
            <thead>
              <tr class="table-header">
                <th>
                  <div
                    style="
                      display: flex;
                      align-items: center;
                      margin-right: 10px;
                      gap: 5px;
                    "
                  >
                    <SvgIcon name="circle"></SvgIcon>

                    {{ $t("headTable1") }}
                  </div>
                </th>
                <th>{{ $t("name") }}</th>
                <th>{{ $t("email") }}</th>
                <th>{{ $t("role") }}</th>
                <th>{{ $t("AllProcedures") }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="user in filteredUsers"
                :key="`user-${user.id}`"
              >
                <td
                  style="
                    display: flex;
                    align-items: center;
                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>
                  {{ user.id }}
                </td>
                <td>{{ user.name }}</td>
                <td>{{ user.email }}</td>
                <td>
                  <div class="role-display">
                    <span v-for="role in user.roles" :key="role.id || role" class="role-tag">
                      {{ role.name || role }}
                    </span>
                    <span v-if="user.roles.length === 0" class="no-role">No roles assigned</span>
                  </div>
                </td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', user)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('view', user)">
                      <SvgIcon class="svg" name="view"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('delete', user)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
  <rolePopup
    v-if="isPopupVisible"
    :type="popupType"
    :data="selectedRow"
    @close="closePopup"
    @save="handleSave"
    @delete="handleDelete"
  />
</template>

<script>
// @ is an alias to /src
import rolePopup from "@/components/dashboard/popus/rolePopup.vue";
import SvgIcon from "@/components/SvgIcon.vue";
import LoadingHere from "@/components/LoadingHere.vue";
import axiosInstance from "@/axios.js";

export default {
  name: "UserSettings",
  components: {
    rolePopup,
    SvgIcon,
    LoadingHere,
  },
  data() {
    return {
      filter: "",
      users: [],
      loading: false,
      error: null,
      isPopupVisible: false,
      popupType: "",
      selectedRow: null,
    };
  },
  computed: {
    filteredUsers() {
      return this.users.filter((user) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof user.name === "string" && user.name.toLowerCase().includes(searchTerm)) ||
          (typeof user.email === "string" && user.email.toLowerCase().includes(searchTerm)) ||
          (Array.isArray(user.roles) && user.roles.some(role => {
            const roleName = typeof role === 'object' ? role.name : role;
            return typeof roleName === "string" && roleName.toLowerCase().includes(searchTerm);
          }))
        );
      });
    },
  },
  mounted() {
    this.fetchUserData();
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
  },
  methods: {
    async fetchUserData() {
      this.loading = true;
      this.error = null;
      
      try {
        const response = await axiosInstance.get('v1/admin/users/get-users-by-role/admin');
        
        if (response.data.status && response.data.data && response.data.data.users) {
          this.users = response.data.data.users;
        } else {
          throw new Error('Invalid response format from API');
        }
      } catch (error) {
        console.error('Error fetching users:', error);
        this.error = error.response?.data?.message || error.message || 'Failed to fetch users';
        
        if (this.$toast) {
          this.$toast.error(this.error);
        }
      } finally {
        this.loading = false;
      }
    },
    openPopup(type, user = null) {
      this.popupType = type;
      this.selectedRow = user
        ? { 
            ...user, 
            roles: [...user.roles], // Clone the roles array
            permissions: user.permissions ? JSON.parse(JSON.stringify(user.permissions)) : {} // Deep clone permissions
          }
        : {
            id: this.users.length > 0
              ? Math.max(...this.users.map((u) => u.id)) + 1
              : 1,
            name: "",
            email: "",
            phone: "",
            roles: [],
            permissions: {},
          };
      this.isPopupVisible = true;
    },
    closePopup() {
      this.isPopupVisible = false;
      this.popupType = "";
      this.selectedRow = null;
    },
    async handleSave(updatedUser) {
      try {
        if (this.popupType === "add") {
          // TODO: Implement API call to add user
          this.users.push(updatedUser);
          if (this.$toast) {
            this.$toast.success("User added successfully");
          }
        } else if (this.popupType === "edit") {
          // TODO: Implement API call to update user
          const index = this.users.findIndex(
            (user) => user.id === updatedUser.id
          );
          if (index !== -1) this.users.splice(index, 1, updatedUser);
          if (this.$toast) {
            this.$toast.success("User updated successfully");
          }
        }
      } catch (error) {
        console.error('Error saving user:', error);
        if (this.$toast) {
          this.$toast.error('Failed to save user');
        }
      }
      this.closePopup();
    },
    async handleDelete(userId) {
      try {
        // TODO: Implement API call to delete user
        this.users = this.users.filter((user) => user.id !== userId);
        if (this.$toast) {
          this.$toast.success("User deleted successfully");
        }
      } catch (error) {
        console.error('Error deleting user:', error);
        if (this.$toast) {
          this.$toast.error('Failed to delete user');
        }
      }
      this.closePopup();
    },
  },
};
</script>
