import { createApp } from "vue";
import App from "./App.vue";
import router from "./router";
import "./assets/main.css";
import store from "./store";
import i18n from "./i18n";
import Toast from 'vue-toastification';
import 'vue-toastification/dist/index.css';
import VueTelInput from 'vue3-tel-input';
import 'vue3-tel-input/dist/vue3-tel-input.css';
import 'axios';
import { library } from '@fortawesome/fontawesome-svg-core';
import { fas } from '@fortawesome/free-solid-svg-icons'; // Solid icons
import { far } from '@fortawesome/free-regular-svg-icons'; // Regular icons
import { fab } from '@fortawesome/free-brands-svg-icons'; // Brand icons
import { FontAwesomeIcon } from '@fortawesome/vue-fontawesome';
import { Chart, registerables } from 'chart.js';

// Register Chart.js components globally
Chart.register(...registerables);

library.add(fas, far, fab);

/* import specific icons */
import { faUserSecret } from '@fortawesome/free-solid-svg-icons';

/* add icons to the library */
library.add(faUserSecret);

const app = createApp(App);

// Make router and store available globally for axios interceptor
window.router = router;
window.store = store;

app.use(Toast)
  .component('font-awesome-icon', FontAwesomeIcon)
  .use(store)
  .use(VueTelInput)
  .use(i18n)
  .use(router)
  .mount("#app");

// Make toast available globally after app is mounted
// We'll access it through the app instance when needed
window.getToast = () => app.config.globalProperties.$toast;

  