          <input v-model="formData.phone" :disabled="type === 'view'" />
        </div>
        <div class="input-container">
          <label>{{ $t("orderDetails") }}</label>
          <input
            type="text"
            v-model="orderDetailInput"
            :disabled="type === 'view'"
            @keyup.enter="addOrderDetail"
            :placeholder="$t('AddorderpressEnter')"
          />
        </div>
        <ul>
          <li
            v-for="(detail, index) in formData.address_description"
            :key="index"
          >
            {{ detail }}
            <button v-if="type !== 'view'" @click="removeOrderDetail(index)">
              ×
            </button>
          </li>
        </ul>
        <div class="input-container">
          <label>{{ $t("TotalPrice") }}</label>
          <input v-model="formData.total_price" :disabled="type === 'view'" />
        </div>
        <div class="input-container">
          <label>{{ $t("RestaurantName") }}</label>
          <select 
            v-model="formData.restaurant_id" 
            :disabled="type === 'view'"
            @change="onRestaurantChange"
          >
            <option value="">{{ $t("SelectRestaurant") }}</option>
            <option 
              v-for="restaurant in restaurants" 
              :key="restaurant.id" 
              :value="restaurant.id"
            >
              {{ restaurant.name }}
            </option>
          </select>
        </div>
        <div class="input-container">
          <label>{{ $t("OrderStatus") }}</label>
          <select v-model="formData.status" :disabled="type === 'view'">
            <option v-for="status in statuses" :key="status" :value="status">
              {{ status }}
            </option>
          </select>
        </div>
        <div class="input-container">
          <label>{{ $t("OrderDate") }}</label>
          <input
            type="date"
            v-model="formData.created_at"
            :disabled="type === 'view'"
          />
        </div>
        <div class="checkbox-container" v-if="type === 'edit'">
          <input
            type="checkbox"
            id="cancelOrder"
            v-model="formData.isCancelled"
            :disabled="type === 'view'"
          />
          <label for="cancelOrder">{{ $t("CancelOrder") }}</label>
        </div>
      </div>

      <p style="text-align: center; color: black" v-if="type === 'delete'">
        {{ $t("confirmDeleteOrder") }}
      </p>
      <p style="text-align: center" v-if="type === 'delete'">
        {{ $t("deleteWarning") }}
      </p>

      <div class="popup-actions">
        <button
          style="background-color: #f02116"
          v-if="type === 'delete'"
          @click="deleteOrder"
        >
          {{ $t("delete") }}
        </button>
        <button v-if="type === 'add' || type === 'edit'" @click="saveOrder">
          {{ $t("Save") }}
        </button>
        <button @click="$emit('close')">{{ $t("Cancel") }}</button>
      </div>
    </div>
  </div>
</template>

<script>
import { useToast } from "vue-toastification";
import axios from "../../../axios.js";

export default {
  props: {
    type: String,
    data: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      formData: {
        ...this.data,
        address_description: Array.isArray(this.data.address_description)
          ? this.data.address_description
          : this.data.address_description
          ? [this.data.address_description] // Convert to array if it's a string
          : [], // Default to an empty array
        status: this.data.status || "new", // Ensure status has a default value
        isCancelled: this.data.isCancelled || false, // Add isCancelled property
        restaurant_id: this.data.restaurant_id || "", // Add restaurant_id property
      },
      orderDetailInput: "",
      statuses: ["new", "waiting", "completed", "processing"], // Ensure statuses are defined
      restaurants: [], // Array to store restaurants from API
      toast: useToast(),
    };
  },
  async mounted() {
    // Fetch restaurants when component is mounted
    await this.fetchRestaurants();
  },
  watch: {
    data: {
      immediate: true,
      handler(newData) {
        this.formData = {
          ...newData,
          address_description: Array.isArray(newData.address_description)
            ? newData.address_description
            : newData.address_description
            ? [newData.address_description] // Convert to array if it's a string
            : [], // Default to an empty array
          status: newData.status || "جديد", // Ensure status has a default value
          isCancelled: newData.isCancelled || false, // Add isCancelled property
          restaurant_id: newData.restaurant_id || "", // Add restaurant_id property
        };
      },
    },
  },
  methods: {
    async fetchRestaurants() {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get(
          "v1/admin/dashboard/get-approved-restaurants",
          {
            headers: {
              "Accept-Language": this.$i18n.locale,
              Authorization: `Bearer ${token}`,
            },
          }
        );
        
        if (response.data.status) {
          this.restaurants = response.data.data.map((item) => ({
            id: item.restaurant.id,
            name: item.restaurant.name || "N/A",
          }));
        } else {
          console.error("Failed to fetch restaurants:", response.data.message);
          this.toast.error(this.$t("FailedToFetchRestaurants"));
        }
      } catch (error) {
        console.error("Error fetching restaurants:", error);
        this.toast.error(this.$t("FailedToFetchRestaurants"));
      }
    },
    onRestaurantChange() {
      // When restaurant is selected, you can add additional logic here if needed
      console.log("Selected restaurant ID:", this.formData.restaurant_id);
    },
    addOrderDetail() {
      if (this.orderDetailInput.trim()) {
        this.formData.address_description.push(this.orderDetailInput.trim());
        this.orderDetailInput = "";
      }
    },
    removeOrderDetail(index) {
      this.formData.address_description.splice(index, 1);
    },
    validateForm() {
      if (
        !this.formData.customerName ||
        this.formData.customerName.trim() === ""
      ) {
        this.toast.error(this.$t("CustomerName") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.phone || this.formData.phone.trim() === "") {
        this.toast.error(this.$t("Phone") + " " + this.$t("isRequired"));
        return false;
      }
      if (
        !this.formData.address_description ||
        this.formData.address_description.length === 0
      ) {
        this.toast.error(this.$t("orderDetails") + " " + this.$t("isRequired"));
        return false;
      }
      if (
        !this.formData.total_price ||
        this.formData.total_price.toString().trim() === ""
      ) {
        this.toast.error(this.$t("TotalPrice") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.restaurant_id || this.formData.restaurant_id === "") {
        this.toast.error(this.$t("RestaurantName") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.status || this.formData.status.trim() === "") {
        this.toast.error(this.$t("OrderStatus") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.created_at || this.formData.created_at.trim() === "") {
        this.toast.error(this.$t("OrderDate") + " " + this.$t("isRequired"));
        return false;
      }
      return true;
    },
    saveOrder() {
      if (this.validateForm()) {
        // Create a copy of formData and ensure restaurant_id is sent
        const orderData = {
          ...this.formData,
          restaurant_id: this.formData.restaurant_id, // Ensure restaurant_id is included
        };
        
        this.$emit("save", orderData);
        this.toast.success(this.$t("OrderSavedSuccessfully"));
      }
    },
    deleteOrder() {
      this.$emit("delete", this.formData.id);
      this.toast.success(this.$t("OrderDeletedSuccessfully"));
    },
  },
};
</script>

