// Authentication utility functions

/**
 * Check if user is authenticated
 * @returns {boolean}
 */
export const isAuthenticated = () => {
  const token = localStorage.getItem("authToken");
  return !!token;
};

/**
 * Get the authentication token
 * @returns {string|null}
 */
export const getAuthToken = () => {
  return localStorage.getItem("authToken");
};

/**
 * Set the authentication token
 * @param {string} token
 */
export const setAuthToken = (token) => {
  localStorage.setItem("authToken", token);
};

/**
 * Clear authentication data and redirect to login
 * @param {Object} router - Vue router instance
 * @param {Object} store - Vuex store instance
 * @param {Object} toast - Toast notification instance
 */
export const logout = (router, store, toast) => {
  // Clear auth token
  localStorage.removeItem("authToken");
  
  // Clear user data from store
  if (store) {
    store.dispatch('setUser', {});
  }
  
  // Show logout message
  if (toast) {
    toast.success("You have been logged out successfully.");
  }
  
  // Redirect to login
  if (router) {
    router.push({ name: 'login' });
  }
};

/**
 * Handle authentication failure
 * @param {Object} router - Vue router instance
 * @param {Object} store - Vuex store instance
 * @param {Object} toast - Toast notification instance
 * @param {string} message - Error message to display
 */
export const handleAuthFailure = (router, store, toast, message = "Authentication failed. Please login again.") => {
  // Clear auth token
  localStorage.removeItem("authToken");
  
  // Clear user data from store
  if (store) {
    store.dispatch('setUser', {});
  }
  
  // Show error message
  if (toast) {
    toast.error(message);
  }
  
  // Redirect to login
  if (router && router.currentRoute.value.name !== 'login') {
    router.push({ name: 'login' });
  }
};

/**
 * Validate token format (basic validation)
 * @param {string} token
 * @returns {boolean}
 */
export const isValidToken = (token) => {
  if (!token) return false;
  
  // Basic JWT token validation (should have 3 parts separated by dots)
  const parts = token.split('.');
  return parts.length === 3;
};

/**
 * Check if token is expired (basic check)
 * @param {string} token
 * @returns {boolean}
 */
export const isTokenExpired = (token) => {
  if (!token) return true;
  
  try {
    // Decode the JWT payload (second part)
    const payload = JSON.parse(atob(token.split('.')[1]));
    const currentTime = Math.floor(Date.now() / 1000);
    
    // Check if token has expired
    return payload.exp && payload.exp < currentTime;
  } catch (error) {
    console.error('Error checking token expiration:', error);
    return true; // Consider invalid tokens as expired
  }
};

/**
 * Refresh authentication check
 * @param {Object} router - Vue router instance
 * @param {Object} store - Vuex store instance
 * @param {Object} toast - Toast notification instance
 * @returns {boolean} - True if authentication is valid, false otherwise
 */
export const checkAuthentication = (router, store, toast) => {
  const token = getAuthToken();
  
  if (!token) {
    handleAuthFailure(router, store, toast, "No authentication token found. Please login again.");
    return false;
  }
  
  if (!isValidToken(token)) {
    handleAuthFailure(router, store, toast, "Invalid authentication token. Please login again.");
    return false;
  }
  
  if (isTokenExpired(token)) {
    handleAuthFailure(router, store, toast, "Authentication token has expired. Please login again.");
    return false;
  }
  
  return true;
}; 