<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <!-- Tabs -->
      <div class="tabs">
        <span
          v-for="(tab, index) in tabs"
          :key="index"
          :class="['tab-item', { active: activeTab === tab.value }]"
          @click="activeTab = tab.value"
        >
          {{ tab.label }}
        </span>
      </div>

      <!-- Tab Content -->
      <div class="tab-content">
        <p v-if="activeTab === 'general'">محتوى التقارير العامة</p>
        <p v-if="activeTab === 'restaurants'">محتوى تقارير المطاعم</p>
        <p v-if="activeTab === 'categories'">محتوى تقارير الأصناف</p>
        <p v-if="activeTab === 'geo'">محتوى التقارير الجغرافية</p>
        <p v-if="activeTab === 'performance'">محتوى تحليلات الأداء</p>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "ReportsAndAnalytics",
  data() {
    return {
      isLoading: false,
      activeTab: 'general',
      tabs: [
        { label: "التقارير العامة", value: "general" },
        { label: "تقارير المطاعم", value: "restaurants" },
        { label: "تقارير الأصناف", value: "categories" },
        { label: "التقارير الجغرافية", value: "geo" },
        { label: "تحليلات الأداء", value: "performance" },
      ],
    };
  },
  mounted() {
    this.isLoading = true;
    this.fetchUserData();
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
  },
  methods: {
    fetchUserData() {
      this.isLoading = false;
    },
  },
};
</script>

<style lang="scss" scoped>
.Control_panel {
  width: calc(100% - 285px);
  max-width: 100%;
  padding: 0 20px;
  box-sizing: border-box;

  @media (min-width: 1200px) {
    margin-left: 284px;
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 284px;
    }
  }

  @media (min-width: 992px) and (max-width: 1199px) {
    margin-left: 285px;
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 285px;
    }
  }

  @media (max-width: 991px) {
    margin-left: 0;
    margin-right: 0;
    padding: 0 15px;
  }
}

.tabs {
  display: flex;
  justify-content: flex-start !important;
  gap: 30px;
  border-bottom: 2px solid #ddd;
  padding-bottom: 5px;
  margin-bottom: 20px;
  @media (min-width: 1200px) {
    margin-left: 10px; /* Width of sidebar */
    
    /* RTL support */
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 10px;
    }
  }
  .tab-item {
    position: relative;
    padding: 10px 5px;
    font-size: 14px;
    color: #333;
    cursor: pointer;
    transition: color 0.3s ease;

    &.active {
      color: #5c0e35;
      font-weight: bold;

      &::after {
        content: "";
        position: absolute;
        bottom: -7px;
        height: 3px;
        background-color: #5c0e35;
        border-radius: 2px;
        inset-inline: 0;
      }
    }

    &:hover {
      color: #5c0e35;
    }
  }

  [dir="rtl"] & {
    justify-content: flex-end;
  }
}


.tab-content {
  padding: 20px 0;
  font-size: 16px;
  color: #333;
  @media (min-width: 1200px) {
    margin-left: 10px; /* Width of sidebar */
    
    /* RTL support */
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 10px;
    }
  }
}
</style>
