<script>
import { useToast } from "vue-toastification";
import axios from "@/axios.js";

export default {
  setup() {
    // Get toast interface
    const toast = useToast();
    return { toast };
  },
  props: {
    type: String,
    data: Object,
  },
  data() {
    return {
      localData: { ...this.data },
      loading: false,
      error: null,
    };
  },
  watch: {
    data: {
      immediate: true,
      handler(newData) {
        this.localData = { ...newData };
        // If it's view mode and we have an ID, fetch the full notification data
        if (this.type === 'view' && newData.id) {
          this.fetchNotification();
        }
      },
    },
  },
  methods: {
    async fetchNotification() {
      if (!this.data.id) return;
      
      this.loading = true;
      this.error = null;
      
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get(`v1/admin/notifications/${this.data.id}`, {
          headers: {
            "Accept-Language": this.$i18n.locale,
            Authorization: `Bearer ${token}`,
          },
        });
        
        if (response.data.status) {
          this.localData = response.data.data;
        } else {
          this.error = response.data.message || this.$t("FailedToLoadNotification");
          this.toast.error(this.error);
        }
      } catch (error) {
        console.error("Error fetching notification:", error);
        this.error = error.response?.data?.message || this.$t("FailedToLoadNotification");
        this.toast.error(this.error);
      } finally {
        this.loading = false;
      }
    },
    
    formatDate(dateString) {
      if (!dateString) return this.$t("NotAvailable");
      try {
        return new Date(dateString).toLocaleString(this.$i18n.locale);
      } catch (error) {
        return dateString;
      }
    },
    
    handleImageUpload(event) {
      const file = event.target.files[0];
      this.uploadFile(file);
    },
    handleDragOver() {
      // Add visual feedback here, like changing the background color
    },
    handleDrop(event) {
      const file = event.dataTransfer.files[0];
      this.uploadFile(file);
    },
    uploadFile(file) {
      if (file) {
        // Image validation
        const validTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
        const maxSizeMB = 2; // max size 2MB
        if (!file.type) {
          this.toast.error("File type is not recognized. Please upload a valid image.");
          return;
        }
        const fileType = file.type.toLowerCase();
        if (!validTypes.includes(fileType)) {
          return;
        }
        if (file.size > maxSizeMB * 1024 * 1024) {
          this.toast.error(`File size exceeds ${maxSizeMB}MB limit.`);
          return;
        }
        const reader = new FileReader();
        reader.onload = (e) => {
          this.localData.image = e.target.result;
          this.toast.success("Image uploaded successfully!");
        };
        reader.onerror = () => {
          this.toast.error("Error reading the file. Please try again.");
        };
        reader.readAsDataURL(file);
      }
    },
    triggerFileInput() {
      this.$refs.fileInput.click();
    },
    save() {
      // Validation logic
      if (
        !this.localData.title ||
        !this.localData.body
      ) {
        this.toast.error("Please fill in all required fields."); // Show error toast
        return;
      }

      if ((this.type === "add" || this.type === "edit") && !this.localData.image) {
        this.toast.error("Please upload an image."); // Show error toast if no image on add or edit
        return;
      }

      if (this.type === "delete") {
        this.$emit("save", this.data);
        this.toast.success("Notification deleted successfully!"); // Show success toast on delete
      } else {
        this.$emit("save", this.localData);
        this.toast.success("Notification saved successfully!"); // Show success toast
      }
    },
  },
};
</script>

