<script>
import axios from "axios";
import { logout, getAuthToken } from "../../utils/auth.js";

export default {
  data() {
    return {
      isDropdownVisible: false,
      isNotificationDropdownVisible: false,
      notifications: [],
      loading: false,
    };
  },

  async created() {
    try {
      const token = getAuthToken();
      if (!token) {
        console.error("No token found. Redirecting to login.");
        if (this.$router) {
          this.$router.push({ name: "login" });
        } else {
          console.error("Router instance is not available.");
        }
        return;
      }
      const response = await axios.get("https://backend.alaqdk.com/api/v1/admin/user", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const userData = response.data;
      this.$store.dispatch('setUser', userData); // Update Vuex store
      this.$emit("user-data", userData);
      if (!userData || Object.keys(userData).length === 0) {
        console.warn("User data is empty or undefined:", userData);
        if (this.$router) {
          this.$router.push({ name: "login" });
        }
      }
      
      // Fetch notifications after user data is loaded
      await this.fetchNotifications();
    } catch (error) {
      console.error("Error fetching user data:", error);
      if (this.$toast) {
        this.$toast.error("Failed to fetch user data. Please log in again.");
      }
      if (this.$router) {
        this.$router.push({ name: "login" });
      }
    }
  },
  
  mounted() {
    // Add click outside listener to close dropdown
    document.addEventListener('click', this.handleClickOutside);
  },
  
  beforeUnmount() {
    // Remove click outside listener
    document.removeEventListener('click', this.handleClickOutside);
  },
  methods: {
    toggleDropdown() {
      this.isDropdownVisible = !this.isDropdownVisible;
    },
    handleClick() {
      logout(this.$router, this.$store, this.$toast);
    },
    changeLanguage(lang) {
      this.$i18n.locale = lang; // Update Vue I18n locale
      localStorage.setItem("lang", lang); // Save language preference
      document.documentElement.setAttribute(
        "dir",
        lang === "ar" ? "rtl" : "ltr"
      ); // Change direction for RTL
    },
    toggleLanguage() {
      const newLang = this.$i18n.locale === "ar" ? "en" : "ar";
      this.changeLanguage(newLang);
    },
    
    handleClickOutside(event) {
      // Close dropdown if clicking outside
      const userProfile = this.$el.querySelector('.user-profile');
      if (userProfile && !userProfile.contains(event.target)) {
        this.isDropdownVisible = false;
      }
      const notificationContainer = this.$el.querySelector('.notification-container');
      if (notificationContainer && !notificationContainer.contains(event.target)) {
        this.isNotificationDropdownVisible = false;
      }
    },

    toggleNotificationDropdown() {
      this.isNotificationDropdownVisible = !this.isNotificationDropdownVisible;
      if (this.isNotificationDropdownVisible) {
        this.fetchNotifications(); // Refresh notifications when dropdown opens
      }
    },

    async fetchNotifications() {
      if (this.loading) return;
      
      this.loading = true;
      try {
        const token = getAuthToken();
        const response = await axios.get("https://backend.alaqdk.com/api/v1/admin/notifications", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        
        if (response.data && response.data.status && response.data.data) {
          this.notifications = response.data.data;
        } else {
          console.error("Invalid notification response structure:", response.data);
          this.notifications = [];
        }
      } catch (error) {
        console.error("Error fetching notifications:", error);
        this.notifications = [];
        if (this.$toast) {
          this.$toast.error("Failed to fetch notifications");
        }
      } finally {
        this.loading = false;
      }
    },

    formatTime(timestamp) {
      const date = new Date(timestamp);
      const now = new Date();
      const diffInSeconds = Math.floor((now - date) / 1000);

      if (diffInSeconds < 60) {
        return `${diffInSeconds}s`;
      } else if (diffInSeconds < 3600) {
        return `${Math.floor(diffInSeconds / 60)}m`;
      } else if (diffInSeconds < 86400) {
        return `${Math.floor(diffInSeconds / 3600)}h`;
      } else {
        return `${Math.floor(diffInSeconds / 86400)}d`;
      }
    },

    async markAsRead(id) {
      try {
        const token = getAuthToken();
        await axios.put(`https://backend.alaqdk.com/api/v1/admin/notifications/${id}/read`, {}, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        
        // Update local state
        this.notifications = this.notifications.map(notification => {
          if (notification.id === id) {
            return { ...notification, is_read: true };
          }
          return notification;
        });
        
        if (this.$toast) {
          this.$toast.success("Notification marked as read.");
        }
      } catch (error) {
        console.error("Error marking notification as read:", error);
        // Update locally even if API fails
        this.notifications = this.notifications.map(notification => {
          if (notification.id === id) {
            return { ...notification, is_read: true };
          }
          return notification;
        });
      }
    },

    async markAllAsRead() {
      try {
        const token = getAuthToken();
        await axios.put("https://backend.alaqdk.com/api/v1/admin/notifications/mark-all-read", {}, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        
        // Update local state
        this.notifications = this.notifications.map(notification => ({ 
          ...notification, 
          is_read: true 
        }));
        
        if (this.$toast) {
          this.$toast.success("All notifications marked as read.");
        }
      } catch (error) {
        console.error("Error marking all notifications as read:", error);
        // Update locally even if API fails
        this.notifications = this.notifications.map(notification => ({ 
          ...notification, 
          is_read: true 
        }));
      }
    },

    async deleteNotification(id) {
      try {
        const token = getAuthToken();
        await axios.delete(`https://backend.alaqdk.com/api/v1/admin/notifications/${id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        
        // Remove from local state
        this.notifications = this.notifications.filter(notification => notification.id !== id);
        
        if (this.$toast) {
          this.$toast.success("Notification deleted successfully.");
        }
      } catch (error) {
        console.error("Error deleting notification:", error);
        if (this.$toast) {
          this.$toast.error("Failed to delete notification.");
        }
      }
    },
  },
  computed: {
    user() {
      return this.$store.getters.user;
    },
    imageTimestamp() {
      return Date.now();
    },
    unreadCount() {
      return this.notifications.filter(notification => !notification.is_read).length;
    }
  }
};
</script>

